{
  "table": {
    "name": "constructors",
    "purpose": "Formula 1 constructors (racing teams): one row per constructor, with its identifier, name, nationality and Wikipedia URL. Referenced by results, standings, qualifying, lap times and pit stops tables."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "constructorId",
      "description": "Primary key; unique numeric identifier of the constructor, referenced by results, qualifying, standings, lap times and pit stops.",
      "status": "resolved"
    },
    "col_002": {
      "role": "identifier",
      "name": "constructorRef",
      "description": "Unique short slug/reference code for the constructor (lowercase, hyphenated, e.g. 'tyrrell', 'cooper-borgward').",
      "status": "resolved"
    },
    "col_003": {
      "role": "category",
      "name": "name",
      "description": "Full display name of the constructor (e.g. 'Alfa Romeo', 'Brabham-Repco').",
      "status": "resolved"
    },
    "col_004": {
      "role": "category",
      "name": "nationality",
      "description": "Constructor's nationality as an adjective (British, American, Italian, etc.).",
      "status": "resolved"
    },
    "col_005": {
      "role": "category",
      "name": "url",
      "description": "Wikipedia URL for the constructor's page.",
      "status": "resolved"
    }
  }
}
